select c1.C_Name as pConstructionUnitName, c2.C_Name as pAgentConstructionUnitName, c3.C_Name as pDesignAndConstructionIntegrationUnitName, c4.C_Name as pAuditUnitName, c5.C_Name as pCostUnitName, c6.C_Name as pCanYanApplyUnitName, c7.C_Name as pCanYanApprovalUnitName, c8.C_Name as pLegalUnitName, c9.C_Name as pRecordIssueUnitName, c10.C_Name as pTransferUnitName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as pAgentConsAbbName, c3.C_Abbreviation as pDesConsIntegAbbName, d.D_Name as pCompetentDepartmentName, parent.P_Name as pParentName, parent.P_code as pParentCode, cpl.P_Name as cplName, f.file_relation_id as fileRelationId, us1.U_Name as pProjectManagerName, us2.U_Name as pProjectLeaderName,us3.U_Name as pEngineerName, us4.U_Name as pEngineerLeaderName,d2.D_Name as pDepartmentName, ,mn.P_Committee_Approva_Document as pCommitteeApprovaDocument,c11.C_Name as pUseUnitName, mn.p_Project_Form_Type_Remark as pProjectFormTypeRemark ,mn.p_Build_Model_Remark as pBuildModelRemark ,mn.p_Professional_Type_Remark as pProfessionalTypeRemark, mn.p_Build_Type_Remark as pBuildTypeRemark, CASE WHEN mn.P_Construction_Start IS NOT NULL THEN YEAR(mn.P_Construction_Start) WHEN mn.P_Create_Time IS NOT NULL THEN YEAR(mn.P_Create_Time) END as projectYear from Pre_Project mn left join SYS_Company c1 on c1.C_Id=mn.P_Construction_Unit left join SYS_Company c2 on c2.C_Id=mn.P_Agent_Construction_Unit left join SYS_Company c3 on c3.C_Id=mn.P_Design_And_Construction_Integration_Unit left join SYS_Company c4 on c4.C_Id=mn.P_Audit_Unit left join SYS_Company c5 on c5.C_Id=mn.P_Cost_Unit left join SYS_Company c6 on c6.C_Id=mn.P_Can_Yan_Apply_Unit left join SYS_Company c7 on c7.C_Id=mn.P_Can_Yan_Approval_Unit left join SYS_Company c8 on c8.C_Id=mn.P_Legal_Unit left join SYS_Company c9 on c9.C_Id=mn.P_Record_Issue_Unit left join SYS_Company c10 on c10.C_Id=mn.P_Transfer_Unit left join SYS_Company c11 on c11.C_Id=mn.P_Use_Unit left join SYS_Department d on mn.P_Competent_Department=d.D_Id left join SYS_Department d2 on mn.P_Department = d2.D_Id left join Pre_Project parent on parent.P_ID=mn.P_Parent_ID left join Pro_Construction_Plan_List cpl on cpl.Cpl_Id=mn.Cpl_Id left join Sys_User us1 on us1.U_Id=mn.P_Project_Manager left join Sys_User us2 on us2.U_Id=mn.P_Project_Leader left join Sys_User us3 on us3.U_Id=mn.P_Engineer left join Sys_User us4 on us4.U_Id=mn.P_Engineer_Leader left join Sys_File f on f.FileID=mn.P_ID
