and likePname(#{params.projectName},mn.P_Id)=true
and mn.P_Name like concat('%',#{params.projectName},'%')
and mn.P_Code like concat('%',#{params.projectCode},'%')
and mn.P_Type = #{params.projectType}
and mn.P_Type IN
